const stock = new Map();
stock.set("pan", 10).set("leche", 5);
console.log(stock.get("pan"));   // 10
console.log(stock.has("queso")); // false
stock.delete("leche");
console.log(stock.size);         // 1

const notas = new Map([["Ana", 18], ["Luis", 14]]);
for (const [nombre, nota] of notas) {
  console.log(nombre, nota); // Ana 18, luego Luis 14
}
console.log([...notas.values()]);       // [18, 14]
console.log(Object.fromEntries(notas)); // { Ana: 18, Luis: 14 }

const nums = [1, 2, 2, 3, 3, 3];
console.log([...new Set(nums)]); // [1, 2, 3]

const vistos = new Set(["ana"]);
vistos.add("luis").add("ana"); // "ana" no se repite
console.log(vistos.size, vistos.has("luis")); // 2 true

const clics = new WeakMap();
const boton = { id: "guardar" }; // en la web sería un elemento del DOM
clics.set(boton, 1);
console.log(clics.get(boton)); // 1

const meta = new Date(2027, 2, 1); // 1 de marzo de 2027 (mes 2 = marzo)
console.log(meta.getFullYear()); // 2027
console.log(meta.toLocaleDateString("es-PE")); // 1/3/2027
const opciones = { weekday: "long", day: "numeric", month: "long" };
console.log(meta.toLocaleDateString("es-PE", opciones)); // lunes, 1 de marzo
const faltan = Math.ceil((meta - new Date()) / 86_400_000); // días que faltan

const soles = new Intl.NumberFormat("es-PE", {
  style: "currency",
  currency: "PEN",
});
console.log(soles.format(1234.5)); // S/ 1,234.50
console.log((0.5).toLocaleString("es-PE", { style: "percent" })); // 50%

const rango = {
  desde: 1,
  hasta: 3,
  *[Symbol.iterator]() {
    for (let i = this.desde; i <= this.hasta; i++) yield i;
  },
};
console.log([...rango]); // [1, 2, 3]

function* contador() {
  let n = 1;
  while (true) yield n++;
}
const gen = contador();
console.log(gen.next().value); // 1
console.log(gen.next().value); // 2
console.log(gen.next());       // { value: 3, done: false }

class Cuenta {
  static moneda = "PEN";
  #saldo = 0; // privado: c.#saldo afuera da error
  constructor(titular) { this.titular = titular; }
  get saldo() { return this.#saldo; }
  set saldo(v) { if (v >= 0) this.#saldo = v; } // valida
}
const c = new Cuenta("Ana"); c.saldo = 50; c.saldo = -9;
console.log(c.saldo, Cuenta.moneda); // 50 PEN

class Animal {
  constructor(nombre) { this.nombre = nombre; }
  hablar() { return `${this.nombre} hace un sonido`; }
}
class Perro extends Animal {
  constructor(nombre, raza) { super(nombre); this.raza = raza; }
  hablar() { return `${super.hablar()}: guau`; }
}
console.log(new Perro("Firulais", "chusco").hablar()); // Firulais hace un sonido: guau

const usuarios = [{ nombre: "Ana", edad: 20 }, { nombre: "Luis", edad: 22 }];
console.table(usuarios); // tabla con columnas (index), nombre, edad

console.time("ordenar");
usuarios.sort((a, b) => b.edad - a.edad);
